(function(){'use strict';let prompt=null,selected=null,distribution=null;const $=id=>document.getElementById(id),ua=navigator.userAgent,ios=/iPhone|iPad|iPod/.test(ua)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1;function choose(platform){selected=platform;$('chooseAndroid').setAttribute('aria-pressed',String(platform==='android'));$('chooseIOS').setAttribute('aria-pressed',String(platform==='ios'));$('device').textContent=platform==='ios'?'iPhone · Safari에서 설치':'Android · APK 또는 홈 화면 설치';const steps=platform==='ios'?['이 페이지를 iPhone의 Safari에서 여세요.','공유 버튼(위쪽 화살표)을 누르세요.','홈 화면에 추가 → 추가를 선택하세요.']:['APK 다운로드 버튼으로 파일을 받으세요.','다운로드한 Pocket-Critters-Android.apk를 열어 설치하세요.','또는 아래 홈 화면 설치를 선택해 파일 없이 이용하세요.'];$('steps').replaceChildren(...steps.map(t=>{let li=document.createElement('li');li.textContent=t;return li}));$('pwa').textContent=platform==='ios'?'iPhone 설치 방법 보기 ↑':'파일 없이 홈 화면에 설치 ＋';$('native').hidden=true;$('apkState').hidden=platform!=='android';if(platform==='android'&&distribution?.android?.status==='ready'&&distribution.android.url){$('native').hidden=false;$('native').href=distribution.android.url;$('apkState').hidden=true}else if(platform==='android')$('apkState').textContent='Android 설치 파일을 만드는 중입니다. 홈 화면 설치는 지금 이용할 수 있어요.';$('guide').textContent=platform==='ios'?'iPhone에는 APK를 설치할 수 없습니다. 홈 화면에 추가하면 앱 아이콘으로 실행할 수 있어요.':'홈 화면 설치도 무료입니다. APK는 개발 테스트용이며 실제 기기 동작은 기종에 따라 확인이 필요합니다.';}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();prompt=e});window.addEventListener('appinstalled',()=>{$('status').textContent='설치되었습니다. 홈 화면의 포켓 크리터즈 아이콘을 눌러주세요.'});$('chooseAndroid').onclick=()=>choose('android');$('chooseIOS').onclick=()=>choose('ios');$('pwa').onclick=async()=>{if(selected==='android'&&prompt){await prompt.prompt();prompt=null}else{$('steps').classList.add('highlight');$('guide').style.color='#ffe3a6';$('steps').scrollIntoView({behavior:'smooth',block:'nearest'})}};choose(ios?'ios':'android');$('status').textContent=location.protocol==='https:'?'무료 설치 · 게임 내용은 다음 실행 또는 업데이트 적용 시 반영됩니다.':'파일 체험 모드입니다. 배포 주소에서 설치해 주세요.';fetch('./distribution.json',{cache:'no-store'}).then(r=>r.json()).then(d=>{distribution=d;choose(selected)}).catch(()=>{});if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});if(matchMedia('(display-mode: standalone)').matches||navigator.standalone)$('status').textContent='이미 앱 모드로 실행 중입니다. 홈 화면에서 바로 이용할 수 있어요.';
})();
